<?php get_header(); if ( function_exists( 'bigshor_wiki_breadcrumbs' ) ) bigshor_wiki_breadcrumbs(); $term = get_search_query(); ?>
<header class="bsw-archive-header"><p class="bsw-eyebrow">BIGSHOR WIKI SEARCH</p><h1 class="page-title">Search results</h1><p class="subtitle">Results for <strong><?php echo esc_html( $term ); ?></strong></p><?php get_search_form(); ?></header>
<nav class="bsw-search-scope" aria-label="Search scope"><a class="is-active" href="<?php echo esc_url( add_query_arg( 'post_type', 'wiki_article', home_url( '/' ) ) ); ?>">Encyclopedia articles</a><a href="<?php echo esc_url( home_url( '/recent-changes/' ) ); ?>">Recent changes</a><a href="<?php echo esc_url( get_post_type_archive_link( 'wiki_article' ) ); ?>">Browse all articles</a></nav>
<?php if ( have_posts() ) : ?><p class="bsw-search-count"><?php global $wp_query; echo esc_html( number_format_i18n( (int) $wp_query->found_posts ) ); ?> matching results</p><ol class="bsw-search-results"><?php while ( have_posts() ) : the_post(); ?><li class="bsw-search-result"><p class="bsw-card-meta"><?php echo esc_html( get_post_type_object( get_post_type() )->labels->singular_name ?? 'Knowledge' ); ?> · Updated <?php echo esc_html( get_the_modified_date() ); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?><a class="bsw-card-link" href="<?php the_permalink(); ?>">Read article</a></li><?php endwhile; ?></ol><nav class="pagination" aria-label="Search pagination"><?php the_posts_pagination(); ?></nav><?php else : ?><section class="bsw-no-results"><h2>No matching pages found</h2><p>Check the spelling, try a broader search, or browse the encyclopedia.</p><a href="<?php echo esc_url( get_post_type_archive_link( 'wiki_article' ) ); ?>">Browse all articles</a></section><?php endif; ?><?php get_footer(); ?>